037D: 0101  IO=A ALL          ; commit the test value into register 90
037E: 02D8  A=0 DPT           ; A = 9000 → reg 90, op 0 (read)
037F: 0AF8  RAM.OP
0380: 0101  IO=A ALL          ; decode: read register 90 back...
0381: 0CD3  B=LOAD MAEX        ; ...into B — TI-59 reads the written value (9009), TI-58 reads 0
0382: 0A27  MOV R5,#2
0383: 02F0  A=R5 DPT           ; A = 9002 → reg 90, op 2 (clear)
0384: 0CF6  D=R5 MAEX
0385: 0AF8  RAM.OP
0386: 0101  IO=A ALL           ; clear register 90 again now the probe is done
; Assemble the expected value (digit-shift R5 into C, four SLC = slide up four
; BCD places) and compare it against B — the value just read back from register
; 90. A match means the high register held the write, i.e. TI-59 memory; the
; result feeds the partition descriptor built below.
